let rows = $input.all().map(item => item.json);

// If Google Sheets has valid data
if (rows.length > 0 && rows[0].sender_id) {

  rows.sort((a, b) => (a.row_number || 0) - (b.row_number || 0));

  const lastFive = rows
    .filter(row => row["User message"] || row["AI reply"])
    .slice(-5);

  // If no usable messages in history, return empty safely
  if (lastFive.length === 0) {
    return [];
  }

  let convo = "";

  lastFive.forEach((msg, i) => {
    if (msg["User message"]) {
      convo += `User message ${i + 1}: ${msg["User message"]}\n`;
    }
    if (msg["AI reply"]) {
      convo += `AI reply ${i + 1}: ${msg["AI reply"]}\n`;
    }
  });

  return [{
    json: {
      source: "google_sheet",
      sender_id: rows[0].sender_id,
      conversation_log: convo.trim(),
      last_5_messages: lastFive
    }
  }];
}

// Fallback only if fallback exists
const fallback = $node["Extracts ID"]?.json;

if (!fallback?.body?.entry?.[0]?.messaging?.[0]) {
  return [];
}

const senderId = fallback.body.entry[0].messaging[0].sender.id;
const userText =
  fallback.body.entry[0].messaging[0].message?.text ||
  fallback.body.entry[0].messaging[0].message_edit?.text ||
  "";

// If no text available, return empty
if (!userText) {
  return [];
}

return [{
  json: {
    source: "instagram_dm",
    sender_id: senderId,
    conversation_log: `User message 1: ${userText}`,
    last_5_messages: [{ conversation_history: userText }]
  }
}];

for (const item of $input.all()) {
  let raw = item.json.output || "";

  // Clean and sanitize raw AI response
  raw = raw.replace(/```json|```/g, "").replace(/\n/g, " ").trim();

  // Try parsing JSON safely
  let data = {};
  try {
    data = JSON.parse(raw);
  } catch (e) {
    item.json.error = "Invalid JSON format";
    continue;
  }

  // Helper function to clean text
  const clean = (str) => (str || "").toString().replace(/\n/g, " ").trim();

  // Extract main response
  item.json.reply = clean(data.reply);
  item.json.intent = clean(data.intent);
  item.json.confidence = clean(data.confidence);
  item.json.next_action = clean(data.next_action);

  // Extract nested lead summary (if available)
  const lead = data.lead_summary || {};
  item.json.problem_summary = clean(lead["Problem Summary"]);
  item.json.need_type = clean(lead["Need Type"]);
  item.json.readiness_level = clean(lead["Readiness Level"]);
  item.json.lead_score = clean(lead["Lead Score"]);
  item.json.coach_notes = clean(lead["Coach Notes"]);

  // Add clean formatted summary for debugging/logs
  item.json.summary_text = `
    Reply: ${item.json.reply}
    Intent: ${item.json.intent}
    Lead Score: ${item.json.lead_score}
    Problem: ${item.json.problem_summary}
  `.trim();
}

return $input.all();

const results = [];

for (const item of $input.all()) {

  // Correctly read AI response
  let raw =
    item.json.content?.parts?.[0]?.text ||
    item.json.message?.content ||
    item.json.message ||
    "";

  try {
    // Remove markdown wrappers
    let clean = raw.replace(/```json|```/g, "").trim();

    // Parse JSON
    const data = JSON.parse(clean);

    // Store clean values
    results.push({
      json: {
        lead_stage: data.lead_stage || "Unqualified",
        reason: data.reason || "No reason returned",
        confidence: data.confidence || "Low"
      }
    });

  } catch (err) {

    // Fallback if parsing fails
    results.push({
      json: {
        lead_stage: "Unqualified",
        reason: "Invalid JSON from AI",
        confidence: "Low"
      }
    });

  }
}

return results;

const outputItems = [];

for (const item of items) {
    if (!item.json.start || !item.json.start.dateTime) continue;

    // Convert startTime from ISO string
    const startTime = new Date(item.json.start.dateTime);

    // Convert current time from $now if available, otherwise use system time
    const now = item.json.$now ? new Date(item.json.$now) : new Date();

    // Calculate difference in hours
    const diffHours = Math.round((startTime - now) / (1000 * 60 * 60));

    outputItems.push({
        json: {
            eventId: item.json.id || null,
            summary: item.json.summary || null,
            hoursUntilStart: diffHours <= 0 ? "0hr" : (diffHours === 1 ? "1hr" : `${diffHours}hrs`)
        }
    });
}

return outputItems;

// Get time value from previous node
const time = $json.time?.toLowerCase()?.trim() || "";

// Allowed time values
const validTimes = ["1hr", "2hrs", "6hrs"];

// Check if matches
const isValid = validTimes.includes(time);

// Return result
return [{ time, isValid }];

// Split the Lead Snapshot into structured fields

for (const item of $input.all()) {
  const snapshot = item.json.Lead_Snapshot || "";

  // Extract key fields using regex
  const name = snapshot.match(/Name:\s*(.*?)(?=\s*- Email|$)/i)?.[1]?.trim() || "";
  const email = snapshot.match(/Email:\s*(.*?)(?=\s*- Date|$)/i)?.[1]?.trim() || "";
  const date = snapshot.match(/Date:\s*(.*?)(?=\s*- Lead Stage|$)/i)?.[1]?.trim() || "";
  const leadStage = snapshot.match(/Lead Stage:\s*(.*?)(?=\s*- Lead Score|$)/i)?.[1]?.trim() || "";
  const leadScore = snapshot.match(/Lead Score:\s*(.*?)(?=\s*- Need Type|$)/i)?.[1]?.trim() || "";
  const needType = snapshot.match(/Need Type:\s*(.*)/i)?.[1]?.trim() || "";

  // Add structured fields to JSON
  item.json = {
    ...item.json,
    Name: name,
    Email: email,
    Date: date,
    Lead_Stage: leadStage,
    Lead_Score: leadScore,
    Need_Type: needType
  };
}

return $input.all();

// n8n Code Node: Split Pre-Call Brief Markdown into JSON sections (with Summary fix)

for (const item of $input.all()) {
  const content = item.json.message?.content || item.json.content || "";

  // Helper function to extract section content safely
  function extractSection(title) {
    const regex = new RegExp(`\\*\\*${title}\\*\\*[\\s\\S]*?(?=\\n\\n---|$)`, "i");
    const match = content.match(regex);
    if (!match) return "not available";

    return match[0]
      .replace(new RegExp(`\\*\\*${title}\\*\\*`, "i"), "")
      .replace(/^-+|\*+|\n+/g, "")
      .trim();
  }

  // Extract each section
  const Lead_Snapshot = extractSection("1\\. Lead Snapshot");
  const Conversation_Summary = extractSection("2\\. Conversation Summary");
  const Problem_Goal = extractSection("3\\. Problem / Goal");
  const Context_Insights = extractSection("4\\. Context & Insights");
  const Preparation_for_Coach = extractSection("5\\. Preparation for Coach");
  const Smart_Questions = extractSection("6\\. Smart Questions to Ask");
  const Recommended_Next_Step = extractSection("7\\. Recommended Next Step");

  // FIX: Capture the Summary section at the end (even if not separated by ---)
  let Summary = "not available";
  const summaryMatch = content.match(/\*\*Summary:\*\*[\s\S]*$/i);
  if (summaryMatch) {
    Summary = summaryMatch[0]
      .replace(/\*\*Summary:\*\*/i, "")
      .trim();
  }

  // Structured JSON output
  item.json = {
    Lead_Snapshot,
    Conversation_Summary,
    Problem_Goal,
    Context_Insights,
    Preparation_for_Coach,
    Smart_Questions,
    Recommended_Next_Step,
    Summary
  };
}

return $input.all();
